{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Norethisterone, a 4-en-3-one steroid with a 17-hydroxy/ethynyl D-ring, has absolute oral bioavailability of 64% in humans, supporting high F for the query's steroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Levonorgestrel, a closely related 19-nor steroid, is reported to be completely bioavailable after oral dosing in humans, indicating that this steroid class can achieve high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Hydrocortisone, a 17-hydroxylated corticosteroid, has absolute oral bioavailability of about 88% in healthy volunteers, showing that 17-hydroxy steroids can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Nomegestrol acetate, a steroidal progestin with a 4-en-3-one, has absolute oral bioavailability of 63.4% in healthy women, supporting high F for the query's steroid core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The closest analogue record reports <10% oral bioavailability for abiraterone acetate, but this is a prodrug with poor solubility and lacks the query's pentafluoroethyl carbinol, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C56"],
      "claim": "Anecortave desacetate is reported to have low oral bioavailability in humans, but this is attributed to first-pass metabolism of the corticosteroid side chain, a feature not present in the query's metabolically stable pentafluoroethyl carbinol.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The weight of human absolute bioavailability data for 4-en-3-one steroids with a 17-hydroxy group strongly favors F ≥20%; the low-F comparators are prodrugs or metabolically labile corticosteroids and are less transferable. The query's high lipophilicity and molecular weight create uncertainty, but the modest 20% threshold and consistent high-F steroid evidence support a high prediction.",
  "evidence_gaps": [
    "No direct experimental ADME data for the query molecule.",
    "No analogues containing the pentafluoroethyl carbinol or methylsulfonylphenyl substituent are present in the evidence set.",
    "Morgan similarities are all below 0.4, limiting structural transferability.",
    "No dose, formulation, solubility, or first-pass metabolism data are available for the query.",
    "The low-F record C11 appears to concern abiraterone acetate, a prodrug, and may not be directly applicable to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

